// how many entries are <= x, using row+column sortedness (bottom-left walk)
int countLessEqual(const vector<vector<int>>& mat, int x) {
    int n = (int)mat.size(), m = (int)mat[0].size();
    int count = 0, r = n - 1, c = 0;
    while (r >= 0 && c < m) {
        if (mat[r][c] <= x) { count += r + 1; ++c; }   // whole column above qualifies
        else                  --r;
    }
    return count;
}

int kthSmallest(const vector<vector<int>>& mat, int k) {
    int lo = mat[0][0], hi = mat.back().back();
    while (lo < hi) {                                   // first value with count >= k
        int mid = lo + (hi - lo) / 2;
        if (countLessEqual(mat, mid) >= k) hi = mid;
        else                               lo = mid + 1;
    }
    return lo;
}

