def count_less_equal(mat: list[list[int]], x: int) -> int:
    """How many entries are <= x, via the bottom-left staircase walk."""
    n, m = len(mat), len(mat[0])
    count, r, c = 0, n - 1, 0
    while r >= 0 and c < m:
        if mat[r][c] <= x:
            count += r + 1        # the whole column above also qualifies
            c += 1
        else:
            r -= 1
    return count


def kth_smallest(mat: list[list[int]], k: int) -> int:
    lo, hi = mat[0][0], mat[-1][-1]
    while lo < hi:                # first value with count >= k
        mid = lo + (hi - lo) // 2
        if count_less_equal(mat, mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

