// entries <= x in the n x m multiplication table (cell (i,j) holds i*j)
long long countLessEqual(int n, int m, long long x) {
    long long count = 0;
    for (int i = 1; i <= n; ++i) {
        if (i > x) break;                    // row i starts at i; nothing qualifies
        count += min((long long)m, x / i);   // j <= x/i, capped at m
    }
    return count;
}

int findKthNumber(int n, int m, int k) {
    long long lo = 1, hi = (long long)n * m;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (countLessEqual(n, m, mid) >= k) hi = mid;
        else                                lo = mid + 1;
    }
    return (int)lo;
}

