def count_le_table(n: int, m: int, x: int) -> int:
    """Entries <= x in the n x m multiplication table (cell (i,j) holds i*j)."""
    count = 0
    for i in range(1, n + 1):
        if i > x:
            break                     # row i starts at i; nothing qualifies
        count += min(m, x // i)       # j <= x//i, capped at m
    return count


def find_kth_number(n: int, m: int, k: int) -> int:
    lo, hi = 1, n * m
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if count_le_table(n, m, mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

