int findPeakUnknownLength(const MountainArray& reader) {
    // Phase 1: double the window until the slope flips or we run past the end
    int hi = 1;
    while (reader.get(hi) != INT_MAX && reader.get(hi) > reader.get(hi - 1))
        hi *= 2;                        // still climbing: the peak is further out
    int lo = hi / 2;                    // the previous probe was still ascending

    // Phase 2: converging slope-bisect, exactly the L2 loop
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        int a = reader.get(mid), b = reader.get(mid + 1);
        if (b == INT_MAX || a > b) hi = mid;      // descending (or past the end)
        else                       lo = mid + 1;  // still climbing
    }
    return lo;
}

