def find_peak_unknown_length(get) -> int:
    """get(i) returns the value at i, or None for out-of-range indices."""
    INF = float('inf')
    def val(i):
        v = get(i)
        return INF if v is None else v

    # Phase 1: double the window until the slope flips or we run past the end
    hi = 1
    while val(hi) != INF and val(hi) > val(hi - 1):
        hi *= 2                       # still climbing: the peak is further out
    lo = hi // 2                      # the previous probe was still ascending

    # Phase 2: converging slope-bisect, exactly the L2 loop
    while lo < hi:
        mid = lo + (hi - lo) // 2
        a, b = val(mid), val(mid + 1)
        if b == INF or a > b:
            hi = mid                  # descending (or past the end)
        else:
            lo = mid + 1              # still climbing
    return lo

