long long sumWithDivisor(const vector<int>& a, int d) {
    long long s = 0;
    for (int x : a) s += (x + d - 1) / d;    // ceil division, no floating point
    return s;
}

int smallestDivisor(const vector<int>& a, int threshold) {
    int lo = 1, hi = *max_element(a.begin(), a.end()), ans = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (sumWithDivisor(a, mid) <= threshold) { ans = mid; hi = mid - 1; }
        else                                       lo = mid + 1;
    }
    return ans;
}

