def sum_with_divisor(a: list[int], d: int) -> int:
    return sum((x + d - 1) // d for x in a)   # ceil division, no floating point


def smallest_divisor(a: list[int], threshold: int) -> int:
    lo, hi = 1, max(a)
    ans = hi
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if sum_with_divisor(a, mid) <= threshold:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

