def pieces_needed(segments: list[float], L: float) -> int:
    """Pieces needed if no piece may exceed length L."""
    pieces, load = 1, 0.0
    for s in segments:
        if load + s > L + 1e-12:      # epsilon guards floating-point noise
            pieces += 1
            load = s
        else:
            load += s
    return pieces


def minimize_longest_piece(segments: list[float], k: int) -> float:
    lo, hi = max(segments), sum(segments)
    for _ in range(100):              # FIXED count, not a convergence test
        mid = lo + (hi - lo) / 2
        if pieces_needed(segments, mid) <= k:
            hi = mid
        else:
            lo = mid
    return hi

