// Strictly unimodal f. Ternary keeps the middle third that must contain the max.
int ternaryArgmax(const vector<int>& f) {
    int lo = 0, hi = (int)f.size() - 1;
    while (hi - lo > 2) {
        int m1 = lo + (hi - lo) / 3;
        int m2 = hi - (hi - lo) / 3;
        if (f[m1] < f[m2]) lo = m1 + 1;    // max cannot be at or left of m1
        else               hi = m2 - 1;    // max cannot be at or right of m2
    }
    int best = lo;
    for (int i = lo + 1; i <= hi; ++i) if (f[i] > f[best]) best = i;
    return best;
}

// Same answer, fewer probes: bisect on the SLOPE instead of comparing two points.
int slopeArgmax(const vector<int>& f) {
    int lo = 0, hi = (int)f.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (f[mid] < f[mid + 1]) lo = mid + 1;
        else                     hi = mid;
    }
    return lo;
}

