def ternary_argmax(f: list[int]) -> int:
    """Strictly unimodal f. Keeps the region that must contain the maximum."""
    lo, hi = 0, len(f) - 1
    while hi - lo > 2:
        m1 = lo + (hi - lo) // 3
        m2 = hi - (hi - lo) // 3
        if f[m1] < f[m2]:
            lo = m1 + 1        # max cannot be at or left of m1
        else:
            hi = m2 - 1        # max cannot be at or right of m2
    best = lo
    for i in range(lo + 1, hi + 1):
        if f[i] > f[best]:
            best = i
    return best


def slope_argmax(f: list[int]) -> int:
    """Same answer, fewer probes: bisect the SLOPE, not two sample points."""
    lo, hi = 0, len(f) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if f[mid] < f[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo
